const frames = [];
const stack = document.querySelector('#stack');
const event = document.querySelector('#event');
const progress = document.querySelector('#progress');
const next = document.querySelector('#step');
let step = 0;
const steps = [
  { push: 4, description: '调用 factorial(4)。' },
  { push: 3, description: '计算 4 × factorial(3)，进入下一层。' },
  { push: 2, description: '计算 3 × factorial(2)，进入下一层。' },
  { push: 1, description: '进入基本情况 factorial(1)。' },
  { description: 'factorial(1) 返回 1，弹出栈帧。' },
  { description: 'factorial(2) 返回 2 × 1 = 2。' },
  { description: 'factorial(3) 返回 3 × 2 = 6。' },
  { description: 'factorial(4) 返回 4 × 6 = 24。' }
];

function render(message) {
  stack.replaceChildren(...[...frames].reverse().map((n) => {
    const frame = document.createElement('li');
    frame.textContent = 'factorial(' + n + ')';
    return frame;
  }));
  progress.textContent = '第 ' + step + ' / ' + steps.length + ' 步';
  event.textContent = message;
  next.disabled = step === steps.length;
}

next.addEventListener('click', () => {
  const action = steps[step++];
  if (action.push) frames.push(action.push);
  else frames.pop();
  render(action.description);
});
document.querySelector('#reset').addEventListener('click', () => {
  step = 0;
  frames.length = 0;
  render('准备执行，调用栈为空。');
});
render('准备执行，调用栈为空。');
